<!DOCTYPE html><html lang="pt-br"><head><meta charset="UTF-8"><meta name="viewport" content="width=device-width, initial-scale=1"><title>Entrar | EcoENEM</title><link rel="icon" href="../imgs/ecoenemicon.png"><link rel="stylesheet" href="../css/auth.css"></head><body><main class="auth-wrap"><section class="auth-card glass"><a class="auth-logo" href="../index.php">EcoENEM</a><h1>Bem-vindo de volta</h1><p class="auth-subtitle">Entre para continuar seus estudos.</p><form id="loginForm"><label for="email">E-mail</label><input id="email" type="email" autocomplete="email" required placeholder="seuemail@exemplo.com"><label for="senha">Senha</label><div class="password-field"><input id="senha" type="password" autocomplete="current-password" required placeholder="Sua senha"><button type="button" class="toggle-password" data-target="senha" aria-label="Mostrar senha">◉</button></div><p class="auth-message" id="mensagem" role="alert"></p><button class="auth-submit" id="entrar" type="submit">Entrar</button></form><p class="auth-foot">Ainda não tem uma conta? <a href="cadastro.php">Criar uma conta</a></p></section></main><script src="https://cdn.jsdelivr.net/npm/@supabase/supabase-js@2"></script><script src="../js/auth.js"></script><script>const emailCampo=document.getElementById('email'), senhaCampo=document.getElementById('senha');document.getElementById('loginForm').addEventListener('submit', async e=>{e.preventDefault();const b=document.getElementById('entrar'),m=document.getElementById('mensagem');b.disabled=true;b.textContent='Entrando...';m.textContent='';try{const cliente=await EcoAuth.client;const {data,error}=await cliente.auth.signInWithPassword({email:emailCampo.value.trim(),password:senhaCampo.value});if(error)throw error;await EcoAuth.sync(data.session);await EcoAuth.registrarAcesso();location.href='../index.php';}catch(err){m.textContent=EcoAuth.mensagemErro(err);}finally{b.disabled=false;b.textContent='Entrar';}});EcoAuth.client.then(async c=>{const {data:{session}}=await c.auth.getSession();if(session){await EcoAuth.sync(session);location.replace('../index.php');}}).catch(()=>{});</script></body></html>
